 } UNION 
 {
 SELECT ?key (COUNT(*) AS ?value) {
 ?x mtp:hasParticipant [] .
 BIND ("Persons mentioned" as ?key ) 
 } group by ?key
 } UNION 
 {
 SELECT ?key (COUNT(distinct ?sub) AS ?value) {
 ?x mtp:hasSubject ?sub .
