 } UNION 
 {
 SELECT ?key (COUNT(distinct ?sub) AS ?value) {
 ?x mtp:hasPlace ?sub .
 BIND ("Places mentions" as ?key ) 
 } group by ?key
 } UNION 
 {
 SELECT ?key (COUNT(*) AS ?value) {
